// Process corrected diagnosis for model retraining
const data = $input.first().json;

const sample = {
  sample_id: `RTR-${Date.now()}`,
  event: 'retraining_sample',
  received_at: new Date().toISOString(),

  // Original prediction
  original_disease: data.original_disease || data.disease || 'Unknown',
  original_confidence: data.original_confidence || data.confidence || 0,
  model_version: data.model_version || 'v1.0',

  // Corrected label (from expert)
  corrected_disease: data.corrected_disease || data.correct_label || '',
  corrected_by: data.corrected_by || 'agronomist',
  correction_source: data.correction_source || 'escalation_review',

  // Image reference
  image_path: data.image_path || '',
  crop: data.crop || '',

  // Metadata
  request_id: data.request_id || '',
  location: data.location || {},

  // Retraining flags
  is_misclassification: data.original_disease !== (data.corrected_disease || data.correct_label),
  needs_review: true,
  added_to_training_set: false,
  status: 'queued'
};

console.log('[Krishi-Sarthi RETRAINING]', JSON.stringify({
  sample_id: sample.sample_id,
  original: sample.original_disease,
  corrected: sample.corrected_disease,
  is_misclassification: sample.is_misclassification
}));

return [{ json: sample }];

// Log the retraining trigger
const sample = $input.first().json;

const logEntry = {
  workflow: 'retraining_trigger',
  timestamp: new Date().toISOString(),
  sample_id: sample.sample_id,
  original_disease: sample.original_disease,
  corrected_disease: sample.corrected_disease,
  is_misclassification: sample.is_misclassification,
  model_version: sample.model_version,
  status: 'logged',

  // Stats tracking
  note: 'In production: aggregate samples and trigger batch retraining when threshold reached'
};

console.log('[Krishi-Sarthi RETRAIN LOG]', JSON.stringify(logEntry));

return [{ json: logEntry }];
